-- Reference meshes use explicit local mounting spaces; old resource identities remain untouched.
create or replace function iam.valid_visual_manifest(value jsonb) returns boolean language sql immutable set search_path='' as $function$
select value is not null and extensions.jsonb_matches_schema($schema${"$schema":"http://json-schema.org/draft-07/schema#","type":"object","properties":{"manifest_version":{"type":"number","const":1},"units":{"type":"string","const":"meters"},"origin":{"type":"string","minLength":1,"maxLength":80,"pattern":"^[a-z][a-z0-9_]*$"},"parameters":{"default":{},"type":"object","properties":{"size_scale":{"type":"number","minimum":0.7,"maximum":1.4},"profile_key":{"type":"string","enum":["commencal-meta-sx-v5","ohlins-rxf38-m3","fox-38-factory-my27","rockshox-vivid-coil-ultimate-d1","marzocchi-bomber-cr","shimano-slx-m7120","shimano-slx-oem-165-32","shimano-sm-bb71-41a","shimano-slx-rd-m7100-sgs","shimano-slx-cs-m7100-12","shimano-slx-cn-m7100","shimano-sm-rt86","dt-swiss-e-593","dt-swiss-350","maxxis-assegai","maxxis-minion-dhr-ii","rockbros-nylon-2017-12","atlas-handlebar-v1","atlas-stem-v1","atlas-saddle-v1","atlas-seatpost-v1","commencal-supreme-dh-v5","fox-40-factory-my27","sram-gx-dh-a3","sram-xg-795","sram-pc1110","sram-dub-pressfit","truvativ-descendant-dh","atlas-potencia-directa","shimano-slx-m7100-brake","magura-mt4","magura-mt5","magura-mt5-pro","magura-mt7-pro","sram-maven-brz-b1","sram-maven-slv-b1","sram-maven-ult-b1","magura-mdr-p","sram-hs2","rockshox-zeb-ultimate-b1","marzocchi-bomber-z1-rail","fox-float-x2-factory-my26","ohlins-ttx22m2-coil","santa-cruz-nomad-7-my27","canyon-sender-cfr-high-pivot","specialized-s-works-enduro-udh","da-bomb-cherry-bomb-29","scott-ransom-rc-427727","trek-slash-al-gen-6","cst-bft-c1752","kenda-pinner-pro-k1241a","michelin-wild-enduro-ms-racing-line","schwalbe-gravity-magic-mary"]},"assembly_version":{"type":"string","const":"atlas-assembly-v5"},"mount_space":{"type":"string","enum":["frame","fork","shock"]}},"additionalProperties":false},"anchors":{"default":{},"type":"object","propertyNames":{"type":"string","pattern":"^[a-z][a-z0-9_]*$"},"additionalProperties":{"type":"object","properties":{"position":{"type":"array","items":[{"type":"number","minimum":-5,"maximum":5},{"type":"number","minimum":-5,"maximum":5},{"type":"number","minimum":-5,"maximum":5}],"additionalItems":false,"minItems":3,"maxItems":3},"rotation":{"type":"array","items":[{"type":"number","minimum":-6.283185307179586,"maximum":6.283185307179586},{"type":"number","minimum":-6.283185307179586,"maximum":6.283185307179586},{"type":"number","minimum":-6.283185307179586,"maximum":6.283185307179586}],"additionalItems":false,"minItems":3,"maxItems":3},"estimated":{"type":"boolean"}},"required":["position","rotation","estimated"],"additionalProperties":false}},"paintable_nodes":{"default":[],"maxItems":128,"type":"array","items":{"type":"string","minLength":1,"maxLength":150}},"selectable_nodes":{"default":[],"maxItems":128,"type":"array","items":{"type":"string","minLength":1,"maxLength":150}}},"required":["manifest_version","units","origin","parameters","anchors","paintable_nodes","selectable_nodes"],"additionalProperties":false}$schema$::json,value);
$function$;
revoke all on function iam.valid_visual_manifest(jsonb) from public,anon,authenticated;
alter table public.visual_assets drop constraint supported_published_generator;
alter table public.visual_assets add constraint supported_published_generator check(not published or kind <> 'procedural' or generator_key in ('atlas-bike-v1','atlas-bike-v2','atlas-bike-v3','atlas-bike-v4','atlas-bike-v5'));
alter table public.visual_assets add constraint visual_v5_requires_profile check(generator_key is distinct from 'atlas-bike-v5' or (manifest->'parameters'->>'profile_key') is not null);
alter table public.visual_assets add constraint glb_mount_contract check(
 (manifest->'parameters'->>'mount_space' is null or (kind='glb' and manifest->'parameters'->>'profile_key' is not null and iam.visual_profile_category(manifest->'parameters'->>'profile_key')=manifest->'parameters'->>'mount_space'))
 and (manifest->'parameters'->>'assembly_version' is null or manifest->'parameters'->>'mount_space' is not distinct from 'frame')
 and (manifest->'parameters'->>'mount_space' is distinct from 'frame' or (manifest->'parameters'->>'assembly_version' is not distinct from 'atlas-assembly-v5' and (manifest->'anchors') ?& array['rear_axle','head_tube','head_tube_lower','seat_tube','shock_upper','shock_lower']))
 and (manifest->'parameters'->>'mount_space' is distinct from 'fork' or (manifest->'anchors') ?& array['axle','lower_crown'])
 and (manifest->'parameters'->>'mount_space' is distinct from 'shock' or (manifest->'anchors') ?& array['upper_eye','lower_eye'])
);
create or replace function iam.enforce_visual_profile() returns trigger language plpgsql security definer set search_path='' as $$
declare expected text;actual text;begin
 if tg_table_name='component_variants' then
  select c.category,iam.visual_profile_category(a.manifest->'parameters'->>'profile_key') into expected,actual
   from public.components c join public.visual_assets a on a.id=new.visual_asset_id and (a.generator_key in ('atlas-bike-v3','atlas-bike-v4','atlas-bike-v5') or a.manifest->'parameters'->>'mount_space' is not null) where c.id=new.component_id;
  if found and expected is distinct from actual then raise exception 'visual_profile_category_mismatch' using errcode='23514';end if;
 elsif tg_table_name='components' then
  if exists(select 1 from public.component_variants v join public.visual_assets a on a.id=v.visual_asset_id where v.component_id=new.id and (a.generator_key in ('atlas-bike-v3','atlas-bike-v4','atlas-bike-v5') or a.manifest->'parameters'->>'mount_space' is not null) and new.category is distinct from iam.visual_profile_category(a.manifest->'parameters'->>'profile_key')) then raise exception 'visual_profile_category_mismatch' using errcode='23514';end if;
 elsif new.generator_key in ('atlas-bike-v3','atlas-bike-v4','atlas-bike-v5') or new.manifest->'parameters'->>'mount_space' is not null then
  if exists(select 1 from public.component_variants v join public.components c on c.id=v.component_id where v.visual_asset_id=new.id and c.category is distinct from iam.visual_profile_category(new.manifest->'parameters'->>'profile_key')) then raise exception 'visual_profile_category_mismatch' using errcode='23514';end if;
 end if;
 return new;
end$$;

-- Public download only. The service process uploads; visitors get no write policy.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
 values('models','models',true,8388608,array['model/gltf-binary','application/octet-stream']) on conflict(id) do nothing;
